import requests
q='("20alpha-hydroxysteroid dehydrogenase" OR "20α-hydroxysteroid dehydrogenase" OR "20alpha-HSD") AND (monkey OR macaque OR primate) AND (promoter OR AP-1 OR CHO)'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':20},timeout=20)
print('status',r.status_code)
ids=r.json()['esearchresult']['idlist']
print('PMIDs',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
else: print('No matching PubMed records')

import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':'25073972','retmode':'xml'},timeout=20)
print('status',r.status_code)
from xml.etree import ElementTree as ET
root=ET.fromstring(r.text)
for a in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(a.itertext()))
for a in root.findall('.//Abstract/AbstractText'):
 print('ABSTRACT:',a.get('Label',''),''.join(a.itertext()))
for a in root.findall('.//ArticleId'):
 if a.get('IdType') in ('doi','pubmed'): print(a.get('IdType'),a.text)
